import React, { useState, useEffect } from 'react'
import { Modal, Button } from 'react-bootstrap'
import axios from 'axios'
import { PageTitle } from '../../../_metronic/layout/core'
import { KTIcon, exportToExcel, exportToCsv, toAbsoluteUrl } from '../../../_metronic/helpers'

interface IBordereau {
    id: string
    num_brd: string
    order_increment_id?: string
    client_name?: string
    seller_name?: string
    created_at: string
    items?: string
    carrier: string
    frais_livraison: number
    total_cod: number
    status?: string
    label_url?: string
    pdf_url?: string
}

const BordereauPage: React.FC = () => {
    const [searchTerm, setSearchTerm] = useState('')
    const [showPdfModal, setShowPdfModal] = useState(false)
    const [showExportModal, setShowExportModal] = useState<boolean>(false)
    const [selectedPdfUrl, setSelectedPdfUrl] = useState('')
    const [bordereaux, setBordereaux] = useState<IBordereau[]>([])
    const [loading, setLoading] = useState(true)
    const [selectedCarrier, setSelectedCarrier] = useState<string>('all')


    useEffect(() => {
        fetchBordereaux();
    }, []);

    const fetchBordereaux = () => {
        setLoading(true);
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:8001/api';
        axios.get(`${apiUrl}/bordereaux`)
            .then(response => {
                const data = response.data;
                // Backend returns { bordereaux: [...], total: ... }
                setBordereaux(Array.isArray(data.bordereaux) ? data.bordereaux : Array.isArray(data) ? data : []);
                setLoading(false);
            })
            .catch(error => {
                console.error("Error fetching bordereaux:", error);
                setBordereaux([]);
                setLoading(false);
            });
    }

    const filteredData = bordereaux.filter(item => {
        const ref = item.order_increment_id || item.num_brd || '';
        const carrier = item.carrier || '';
        const customer = item.client_name || '';
        const seller = item.seller_name || '';
        const term = searchTerm.toLowerCase();

        const matchesSearch = (
            ref.toLowerCase().includes(term) ||
            carrier.toLowerCase().includes(term) ||
            customer.toLowerCase().includes(term) ||
            seller.toLowerCase().includes(term)
        );

        const matchesCarrier = selectedCarrier === 'all' || carrier === selectedCarrier;

        return matchesSearch && matchesCarrier;
    });

    const carriers = Array.from(new Set(bordereaux.map(b => b.carrier).filter(Boolean)));


    const handleShowPdf = (url: string) => {
        setSelectedPdfUrl(url)
        setShowPdfModal(true)
    }

    const handleClosePdfModal = () => {
        setShowPdfModal(false)
        setSelectedPdfUrl('')
    }

    const getExportData = () => {
        return filteredData.map(item => ({
            "Reference / Order": item.order_increment_id,
            "AWB / Tracking": item.num_brd,
            "Date": item.created_at,
            "Customer": item.client_name || 'N/A',
            "Seller": item.seller_name || 'N/A',
            "Carrier": item.carrier,
            "Frais": item.frais_livraison,
            "COD": item.total_cod,
            "Label URL": item.label_url
        }));
    };

    const handleExportCsv = () => {
        const dataToExport = getExportData();
        exportToCsv(dataToExport, 'bordereaux_export');
        setShowExportModal(false);
    };

    const handleExportXls = () => {
        const dataToExport = getExportData();
        exportToExcel(dataToExport, 'bordereaux_export', 'Bordereaux');
        setShowExportModal(false);
    };

    return (
        <>
            <PageTitle breadcrumbs={[]}>Historique des Bordereaux</PageTitle>

            <div className='card mb-5 mb-xl-8'>
                <div className='card-header border-0 pt-5'>
                    <h3 className='card-title align-items-start flex-column'>
                        <span className='card-label fw-bold fs-3 mb-1'>Bordereaux History</span>
                        <span className='text-muted mt-1 fw-semibold fs-7'>All shipping labels and PDFs generated during order processing</span>
                    </h3>
                    <div className='card-toolbar'>
                        <div className='d-flex align-items-center position-relative my-1'>
                            <KTIcon iconName='magnifier' className='fs-1 position-absolute ms-6' />
                            <input
                                type='text'
                                className='form-control form-control-solid w-250px ps-14'
                                placeholder='Search bordereau...'
                                value={searchTerm}
                                onChange={(e) => setSearchTerm(e.target.value)}
                            />
                        </div>
                        <div className='d-flex align-items-center position-relative my-1 ms-3'>
                            <select
                                className='form-select form-select-solid w-150px'
                                value={selectedCarrier}
                                onChange={(e) => setSelectedCarrier(e.target.value)}
                            >
                                <option value='all'>All Carriers</option>
                                {carriers.map(carrier => (
                                    <option key={carrier} value={carrier}>{carrier}</option>
                                ))}
                            </select>
                        </div>

                        <button
                            className='btn btn-sm btn-light-success ms-3'
                            onClick={() => setShowExportModal(true)}
                        >
                            <KTIcon iconName='exit-up' className='fs-2' />
                            Export
                        </button>
                        <button
                            className='btn btn-sm btn-light-primary ms-3'
                            onClick={fetchBordereaux}
                        >
                            <KTIcon iconName='arrows-circle' className='fs-2' />
                            Refresh
                        </button>
                    </div>
                </div>
                <div className='card-body py-3'>
                    <div className='table-responsive'>
                        <table className='table table-row-bordered table-row-gray-100 align-middle gs-0 gy-3'>
                            <thead>
                                <tr className='fw-bold text-muted'>
                                    <th className='min-w-80px'><KTIcon iconName='file' className='fs-3 me-1' />PDF</th>
                                    <th className='min-w-100px'><KTIcon iconName='barcode' className='fs-3 me-1' />AWB / Tracking</th>
                                    <th className='min-w-100px'><KTIcon iconName='hash' className='fs-3 me-1' />Order Ref</th>
                                    <th className='min-w-140px'><KTIcon iconName='calendar' className='fs-3 me-1' />Date</th>
                                    <th className='min-w-120px'><KTIcon iconName='profile-circle' className='fs-3 me-1' />Customer</th>
                                    <th className='min-w-120px'><KTIcon iconName='shop' className='fs-3 me-1' />Seller</th>
                                    <th className='min-w-100px'><KTIcon iconName='delivery-3' className='fs-3 me-1' />Carrier</th>
                                    <th className='min-w-100px'><KTIcon iconName='toggle-on-circle' className='fs-3 me-1' />Status</th>
                                    <th className='min-w-100px'><KTIcon iconName='wallet' className='fs-3 me-1' />Total COD</th>
                                    <th className='min-w-100px text-end'>Actions</th>
                                </tr>
                            </thead>
                            <tbody>
                                {loading ? (
                                    <tr>
                                        <td colSpan={10} className='text-center py-10'>
                                            <span className='spinner-border text-primary'></span>
                                        </td>
                                    </tr>
                                ) : filteredData.length > 0 ? (
                                    filteredData.map((item, index) => (
                                        <tr key={index}>
                                            <td className='text-center'>
                                                {(item.pdf_url || item.label_url) ? (
                                                    <a
                                                        href={item.pdf_url || item.label_url}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        className='btn btn-icon btn-bg-light btn-active-color-primary btn-sm me-1'
                                                        title='Download PDF'
                                                    >
                                                        <img src={toAbsoluteUrl('/media/svg/files/pdf.svg')} className='h-20px' alt='pdf' />
                                                    </a>
                                                ) : (
                                                    <span className='badge badge-light-secondary'>
                                                        <KTIcon iconName='file' className='fs-4' />
                                                    </span>
                                                )}
                                            </td>
                                            <td className='text-dark fw-bold fs-6'>
                                                <span className='badge badge-light-info'>{item.num_brd}</span>
                                            </td>
                                            <td className='text-dark fw-bold text-hover-primary fs-6'>
                                                {item.order_increment_id}
                                            </td>
                                            <td className='text-muted fw-bold fs-6'>{item.created_at}</td>
                                            <td className='text-gray-800 fw-bold fs-6'>{item.client_name || 'N/A'}</td>
                                            <td className='text-gray-800 fw-bold fs-6'>{item.seller_name || 'N/A'}</td>
                                            <td className='text-primary fw-bold fs-6'>{item.carrier}</td>
                                            <td>
                                                {item.status === 'delivered' ? (
                                                    <span className='badge badge-light-success'>Delivered</span>
                                                ) : item.status === 'shipped' ? (
                                                    <span className='badge badge-light-info'>Shipped</span>
                                                ) : item.status === 'pending' ? (
                                                    <span className='badge badge-light-warning'>Pending</span>
                                                ) : item.status === 'created' ? (
                                                    <span className='badge badge-light-primary'>Created</span>
                                                ) : item.status === 'assigned' ? (
                                                    <span className='badge badge-light-info'>Assigned</span>
                                                ) : item.status === 'canceled' ? (
                                                    <span className='badge badge-light-danger'>Canceled</span>
                                                ) : item.status === 'returned' ? (
                                                    <span className='badge badge-light-warning'>Returned</span>
                                                ) : item.status === 'lost' ? (
                                                    <span className='badge badge-light-danger'>Lost</span>
                                                ) : (
                                                    <span className='badge badge-light-dark'>{item.status || 'Unknown'}</span>
                                                )}
                                            </td>
                                            <td className='text-success fw-bold fs-6'>{item.total_cod} TND</td>
                                            <td className='text-end'>
                                                {(item.pdf_url || item.label_url) && (
                                                    <a
                                                        href={item.pdf_url || item.label_url}
                                                        target="_blank"
                                                        rel="noopener noreferrer"
                                                        className='btn btn-icon btn-bg-light btn-active-color-primary btn-sm me-1'
                                                        title='Download PDF'
                                                    >
                                                        <KTIcon iconName='cloud-download' className='fs-3 text-primary' />
                                                    </a>
                                                )}
                                                <button
                                                    className='btn btn-icon btn-bg-light btn-active-color-primary btn-sm'
                                                    title='View Preview'
                                                    onClick={() => handleShowPdf(item.pdf_url || item.label_url || '')}
                                                    disabled={!item.pdf_url && !item.label_url}
                                                >
                                                    <KTIcon iconName='eye' className='fs-3 text-info' />
                                                </button>
                                            </td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan={10} className='text-center py-10'>
                                            <div className='d-flex flex-column align-items-center'>
                                                <KTIcon iconName='file-deleted' className='fs-3x text-muted mb-4' />
                                                <h5 className='text-muted mb-2'>No bordereaux generated yet</h5>
                                                <p className='text-gray-600 fs-7'>
                                                    Process orders from the "Orders To Confirm" page to generate shipping labels and PDFs
                                                </p>
                                            </div>
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            {/* Label Preview Modal */}
            <Modal show={showPdfModal} onHide={handleClosePdfModal} size="xl">
                <Modal.Header closeButton>
                    <Modal.Title>Label Preview</Modal.Title>
                </Modal.Header>
                <Modal.Body className="p-0" style={{ height: '80vh' }}>
                    <iframe
                        src={`${selectedPdfUrl}#toolbar=0&navpanes=0&scrollbar=0`}
                        title="PDF Viewer"
                        width="100%"
                        height="100%"
                        style={{ border: 'none' }}
                    />
                </Modal.Body>
                <Modal.Footer>
                    <Button variant="secondary" onClick={handleClosePdfModal}>
                        Close
                    </Button>
                    {selectedPdfUrl && (
                        <a href={selectedPdfUrl} target="_blank" rel="noopener noreferrer" className="btn btn-primary">
                            Open in New Tab
                        </a>
                    )}
                </Modal.Footer>
            </Modal>

            <Modal show={showExportModal} onHide={() => setShowExportModal(false)} centered>
                <Modal.Header closeButton>
                    <Modal.Title>Export Options</Modal.Title>
                </Modal.Header>
                <Modal.Body className="text-center py-10">
                    <p className="text-gray-600 mb-8 fs-5">Choose the format you want to export the data in:</p>
                    <div className="d-flex justify-content-center gap-4">
                        <button className="btn btn-outline btn-outline-dashed btn-outline-success btn-active-light-success px-10 py-5" onClick={handleExportCsv}>
                            <i className="bi bi-filetype-csv fs-1 mb-2 d-block"></i>
                            <span className="fw-bold fs-5">CSV</span>
                        </button>
                        <button className="btn btn-outline btn-outline-dashed btn-outline-primary btn-active-light-primary px-10 py-5" onClick={handleExportXls}>
                            <i className="bi bi-filetype-xls fs-1 mb-2 d-block"></i>
                            <span className="fw-bold fs-5">XLS</span>
                        </button>
                    </div>
                </Modal.Body>
            </Modal>
        </>
    )
}

export default BordereauPage
